animation_ir.css:
@keyframes ir-fade-up { from { opacity: 0; transform: translate3d(0, 16px, 0); } to { opacity: 1; transform: translate3d(0, 0, 0); } }
@keyframes ir-pop { 0% { opacity: 0; transform: scale(0.85); } 60% { opacity: 1; transform: scale(1.04); } 100% { transform: scale(1); } }
@keyframes ir-draw { from { stroke-dashoffset: var(--draw-length, 1000); } to { stroke-dashoffset: 0; } }
@keyframes ir-fade { from { opacity: 0; } to { opacity: 1; } }
.ir-anim-entry-headline { animation: ir-fade-up 0.380s ease-out 0.060s 1 both; }
.ir-anim-entry-nodes { animation: ir-pop 0.360s ease-out 0.200s 1 both; }
.ir-anim-entry-edges { animation: ir-draw 0.600s ease-in-out 0.600s 1 both; }
.ir-anim-exit-all { animation: ir-fade 0.220s ease-in 0.000s 1 both; }
@media (prefers-reduced-motion: reduce) { [class*='ir-anim-'] { animation-duration: 0.001s !important; animation-delay: 0s !important; } }

